def P(x):
    """Calculates 29x^4 - 173x^3 + 87x - 432"""
    return 29 * (x**4) - 173 * (x**3) + 87 * x - 432

# Test x_2 values starting from 19
for x2 in range(19, 51):
    if x2 % 3 == 2:
        # x3 would not be an integer
        continue

    if P(x2) == 0:
        print(f"Found integer root x2 = {x2}")
        # We also need to ensure x2 >= 19, which is handled by the range.
        # Check x3 integer condition again (redundant, but good practice)
        if (x2**3 - x2**2) % 3 == 0:
             print(f"x3 is integer for x2 = {x2}")
        else:
             print(f"x3 is NOT integer for x2 = {x2}")

# Check a few values just in case the root is higher
print("Testing P(50):", P(50))
